#!/usr/bin/env python3
"""RetinaScope SEO upgrade. Run from the project root; no extra packages."""
from pathlib import Path
import base64, re, shutil, tempfile, sys

root=Path.cwd()
if not (root/'frontend/app/layout.tsx').is_file():
    root=Path(__file__).resolve().parent
if not (root/'frontend/app/layout.tsx').is_file():
    sys.exit('Open terminal inside retinaScope-Final (the folder containing frontend and backend), then run this script.')
app=root/'frontend/app'
url='https://retina-scope-final.vercel.app'
changes={}
def read(p): return p.read_text(encoding='utf-8')
def replace_once(text,old,new,label):
    if text.count(old)!=1: sys.exit('No files changed. Expected one match for '+label+'. Your code may have changed; ask for an updated patch.')
    return text.replace(old,new,1)
layout=app/'layout.tsx'; s=read(layout)
metadata='''export const metadata: Metadata = {
  metadataBase: new URL("https://retina-scope-final.vercel.app"),
  title: "RetinaScope AI | Explainable Diabetic Retinopathy Screening",
  description: "RetinaScope AI by Team Shadow is a research prototype for diabetic retinopathy screening with EfficientNet-B0, single- and dual-eye analysis, Grad-CAM and district-level planning.",
  applicationName: "RetinaScope AI",
  alternates: { canonical: "/" },
  robots: { index: true, follow: true },
  openGraph: {
    title: "RetinaScope AI | Explainable Retinal Screening",
    description: "Explore the Team Shadow research prototype for retinal image analysis, Grad-CAM and healthcare resource planning.",
    url: "https://retina-scope-final.vercel.app/",
    siteName: "RetinaScope AI",
    type: "website",
    locale: "en_IN",
  },
  twitter: {
    card: "summary",
    title: "RetinaScope AI | Explainable Retinal Screening",
    description: "A research prototype for AI-assisted diabetic retinopathy screening and district planning.",
  },
};'''
s,n=re.subn(r'export const metadata: Metadata = \{.*?\n\};',lambda _:metadata,s,count=1,flags=re.S)
if n!=1: sys.exit('No files changed: metadata block not found.')
changes[layout]=s.encode()
page=app/'page.tsx'; s=read(page)
if 'id="retinascope-website-schema"' not in s:
    s=replace_once(s,'<main className="app-shell">','''<main className="app-shell">
      <script id="retinascope-website-schema" type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify({ "@context": "https://schema.org", "@type": "WebSite", name: "RetinaScope AI", alternateName: "RetinaScope", url: "https://retina-scope-final.vercel.app/" }).replace(/</g, "\\\\u003c") }} />''','homepage root')
    s=replace_once(s,'<span className="hero-title-line"><span>See</span> <span>beyond</span></span>\n            <span className="hero-title-line"><span>the</span> <em>image.</em></span>','''<span className="hero-title-line"><span>RetinaScope</span></span>
            <span className="hero-title-line"><span>AI</span> <em>screening.</em></span>''','homepage H1')
    s=replace_once(s,'A clearer view of diabetic retinopathy screening. Bring retinal imagery, explainable AI and practical screening insights into one focused workspace.','RetinaScope AI by Team Shadow is an explainable diabetic retinopathy screening research platform. Explore single- and dual-eye retinal image analysis, Grad-CAM visual explanations and district-level healthcare planning.','homepage description')
    s=replace_once(s,'<a className="button button-primary closing-cta" href="#workspace">Open screening workspace <Icon name="arrow" size={18} /></a>','''<a className="button button-primary closing-cta" href="#workspace">Open screening workspace <Icon name="arrow" size={18} /></a>
        <a className="text-link" href="/methodology">Read the RetinaScope AI research methodology <span aria-hidden="true">↗</span></a>''','methodology link')
changes[page]=s.encode()
method=app/'methodology/page.tsx'
method_content='''import type { Metadata } from "next";
import Link from "next/link";

export const metadata: Metadata = {
  title: "RetinaScope AI Research Methodology | Team Shadow",
  description: "Learn how RetinaScope AI processes fundus images, classifies diabetic retinopathy, produces Grad-CAM explanations and supports district planning, including research limitations.",
  alternates: { canonical: "/methodology" },
  openGraph: {
    title: "RetinaScope AI Research Methodology",
    description: "Model architecture, screening workflow and limitations of the Team Shadow research prototype.",
    url: "https://retina-scope-final.vercel.app/methodology",
    siteName: "RetinaScope AI",
    type: "website",
  },
};

export default function MethodologyPage() {
  return (
    <main style={{ maxWidth: 920, margin: "0 auto", padding: "64px 24px", lineHeight: 1.8 }}>
      <Link href="/" style={{ textDecoration: "underline" }}>← RetinaScope AI home</Link>
      <p style={{ marginTop: 32, fontWeight: 600 }}>TEAM SHADOW / RESEARCH &amp; DEMONSTRATION</p>
      <h1 style={{ fontSize: "clamp(2rem, 5vw, 3.5rem)", lineHeight: 1.15, margin: "16px 0 24px" }}>RetinaScope AI research methodology</h1>
      <p>RetinaScope AI explores explainable screening of diabetic retinopathy from retinal fundus photographs. The project combines image classification, visual explanations, comparison of both eyes and district-level screening resource planning.</p>
      <section style={{ marginTop: 32 }}>
        <h2>Retinal image processing and model</h2>
        <p>Fundus images are resized to 224 × 224 pixels, contrast-enhanced using CLAHE, lightly denoised and normalized. A trained EfficientNet-B0 model produces scores for five diabetic retinopathy grades: no DR, mild, moderate, severe and proliferative DR. The application supports one or two uploaded retinal images.</p>
      </section>
      <section style={{ marginTop: 32 }}>
        <h2>Explainable AI with Grad-CAM</h2>
        <p>Gradient-weighted class activation mapping visualizes regions contributing to a predicted class. The heatmap is an explanation of model behavior, not a verified lesion annotation or proof of a diagnosis. Both eyes can be reviewed separately in dual-eye mode.</p>
      </section>
      <section style={{ marginTop: 32 }}>
        <h2>Model evaluation and limitations</h2>
        <p>The deployed checkpoint records internal validation accuracy of approximately 80.08% and macro F1 of 0.6486. These figures are project validation results, not independent clinical validation. External evaluation, calibration, image-quality assessment and prospective clinical studies are needed before clinical use. Model confidence is not a calibrated probability of disease.</p>
      </section>
      <section style={{ marginTop: 32 }}>
        <h2>District-level healthcare planning</h2>
        <p>The planning interface explores estimated screening demand, capacity gaps and priorities using district-level project data. These estimates are illustrative planning inputs rather than independently verified service inventories or individual patient records.</p>
      </section>
      <section style={{ marginTop: 32 }}>
        <h2>Responsible use and image privacy</h2>
        <p>RetinaScope AI is a research and demonstration prototype, not a medical device or a substitute for professional examination. Live analysis sends the selected file to the hosted backend. Use only authorized, de-identified demonstration images; do not upload identifiable patient information. Screening results require qualified eye-care professional review.</p>
      </section>
      <section style={{ marginTop: 32 }}>
        <h2>Project source and technical references</h2>
        <p>Explore the <a href="https://github.com/Harshit0717-cpu/retinaScope-Final" style={{ textDecoration: "underline" }}>RetinaScope AI source repository</a>, including the Next.js frontend and FastAPI/PyTorch backend.</p>
        <p><a href="https://proceedings.mlr.press/v97/tan19a.html" style={{ textDecoration: "underline" }}>EfficientNet: Rethinking Model Scaling for Convolutional Neural Networks (2019)</a> · <a href="https://arxiv.org/abs/1610.02391" style={{ textDecoration: "underline" }}>Grad-CAM: Visual Explanations from Deep Networks via Gradient-based Localization</a></p>
      </section>
      <p style={{ marginTop: 40 }}><Link href="/" style={{ textDecoration: "underline" }}>Return to the screening workspace</Link></p>
    </main>
  );
}
'''
if method.exists() and read(method)!=method_content: sys.exit('No files changed: an existing methodology page would be overwritten.')
changes[method]=method_content.encode()
changes[app/'sitemap.xml']=('''<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url><loc>https://retina-scope-final.vercel.app/</loc></url>
  <url><loc>https://retina-scope-final.vercel.app/methodology</loc></url>
</urlset>
''').encode()
changes[app/'favicon.ico']=base64.b64decode('')
readme=root/'README.md'; s=read(readme)
if url not in s:
    s='# RetinaScope AI — Team Shadow\n\n**Live research demo:** [RetinaScope AI]('+url+'/).\n\n[Research methodology and limitations]('+url+'/methodology)\n\n'+s
    changes[readme]=s.encode()
backup=Path(tempfile.mkdtemp(prefix='retinascope-seo-backup-'))
for p in changes:
    if p.exists():
        b=backup/p.relative_to(root); b.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,b)
for p,data in changes.items():
    p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(data)
    print('Updated:',p.relative_to(root))
print('\nBackup:',backup)
print('SEO changes applied locally. Run npm run build inside frontend, then commit and push the changes. Backend and verification file untouched.')
